const $=id=>document.getElementById(id);
const scene=new THREE.Scene();scene.background=new THREE.Color(0x9bbdb7);scene.fog=new THREE.FogExp2(0x9bbdb7,.0048);
const camera=new THREE.PerspectiveCamera(62,innerWidth/innerHeight,.1,420);
