scene.add(new THREE.HemisphereLight(0xdff4ee,0x645744,2.1));
const sun=new THREE.DirectionalLight(0xffe6bc,3.2);sun.position.set(-45,70,30);sun.castShadow=true;sun.shadow.mapSize.set(1024,1024);sun.shadow.camera.left=-100;sun.shadow.camera.right=100;sun.shadow.camera.top=100;sun.shadow.camera.bottom=-100;scene.add(sun);
const mat=(color,rough=.8)=>new THREE.MeshStandardMaterial({color,roughness:rough});
const mats={grass:mat(0x777e47),grass2:mat(0x87814a),sand:mat(0xc0ad78),trunk:mat(0x58432f),leaf:mat(0x3c6647),leaf2:mat(0x54784b),roof:mat(0x874e38),wall:mat(0xcbbd9a),wall2:mat(0x777c70),dark:mat(0x222c2d),player:mat(0x374b40),pants:mat(0x303a36),skin:mat(0xc68a62),gun:mat(0x303639),enemy:mat(0xb55240),enemy2:mat(0x3c4849),yellow:mat(0xd4c75f),rock:mat(0x77776b)};
const ground=new THREE.Mesh(new THREE.PlaneGeometry(500,500),mat(0x729e9a));ground.rotation.x=-Math.PI/2;ground.position.y=-1.7;ground.receiveShadow=true;scene.add(ground);
const SIZE=180,SEG=72,verts=[],inds=[];
function heightAt(x,z){const r=Math.hypot(x,z);return 1.4*Math.sin(x*.063)*Math.cos(z*.051)+.8*Math.sin((x+z)*.11)+Math.max(0,1-r/100)*2.2+Math.max(0,r-72)*.11}
for(let iz=0;iz<=SEG;iz++)for(let ix=0;ix<=SEG;ix++){const x=(ix/SEG-.5)*SIZE,z=(iz/SEG-.5)*SIZE,r=Math.hypot(x,z);const edge=Math.max(0,1-Math.max(0,r-70)/20);verts.push(x,heightAt(x,z)*edge,z)}
for(let z=0;z<SEG;z++)for(let x=0;x<SEG;x++){const a=z*(SEG+1)+x,b=a+1,c=a+SEG+1,d=c+1;inds.push(a,c,b,b,c,d)}
const geo=new THREE.BufferGeometry();geo.setAttribute('position',new THREE.Float32BufferAttribute(verts,3));geo.setIndex(inds);geo.computeVertexNormals();geo.setAttribute('color',new THREE.Float32BufferAttribute(verts.flatMap((_,i)=>{if(i%3!==0)return [];const y=verts[i+1];const variation=Math.sin(i*12.98)*.045;const c=new THREE.Color(y<.3?0x9d925e:0x82904e);c.offsetHSL(0,0,variation);return [c.r,c.g,c.b]}),3));
const terrain=new THREE.Mesh(geo,new THREE.MeshStandardMaterial({vertexColors:true,roughness:1}));terrain.receiveShadow=true;terrain.castShadow=false;scene.add(terrain);
// distant ridge silhouettes
for(let i=0;i<18;i++){const a=i/18*Math.PI*2,r=118+Math.sin(i*8)*5;const h=18+Math.random()*18;const hill=new THREE.Mesh(new THREE.ConeGeometry(16+Math.random()*9,h,7),mat(i%2?0x778b83:0x71847c));hill.position.set(Math.cos(a)*r,h/2-2,Math.sin(a)*r);hill.rotation.y=Math.random()*3;scene.add(hill)}
function box(parent,w,h,d,material,x,y,z){const m=new THREE.Mesh(new THREE.BoxGeometry(w,h,d),material);m.position.set(x,y,z);m.castShadow=true;m.receiveShadow=true;parent.add(m);return m}
function tree(x,z,scale=1){const g=new THREE.Group();g.position.set(x,heightAt(x,z),z);const trunk=new THREE.Mesh(new THREE.CylinderGeometry(.28*scale,.48*scale,3.6*scale,6),mats.trunk);trunk.position.y=1.8*scale;trunk.castShadow=true;g.add(trunk);for(let i=0;i<3;i++){const crown=new THREE.Mesh(new THREE.ConeGeometry((2.3-i*.23)*scale,3.8*scale,7),i===1?mats.leaf2:mats.leaf);crown.position.y=(3.1+i*1.35)*scale;crown.rotation.y=i*1.7;crown.castShadow=true;g.add(crown)}scene.add(g)}
function rock(x,z,s=1){const m=new THREE.Mesh(new THREE.DodecahedronGeometry(s,0),mats.rock);m.position.set(x,heightAt(x,z)+s*.45,z);m.scale.set(1.25,.78,.9);m.castShadow=true;m.receiveShadow=true;scene.add(m)}
// buildings with simple veranda, dark windows, and corrugated roof
function hut(x,z,s=1,rotation=0){const g=new THREE.Group();g.position.set(x,heightAt(x,z),z);g.rotation.y=rotation;box(g,9*s,4.2*s,7*s,mats.wall,0,2.1*s,0);box(g,9.8*s,.35*s,7.8*s,mats.dark,0,4.35*s,0);const roof=new THREE.Mesh(new THREE.ConeGeometry(6.7*s,3*s,4),mats.roof);roof.position.y=5.8*s;roof.rotation.y=Math.PI/4;roof.scale.z=.78;roof.castShadow=true;g.add(roof);box(g,1.2*s,2.5*s,.18*s,mats.trunk,0,1.25*s,3.57*s);for(const xx of [-2.7,2.7]){box(g,1.35*s,1.2*s,.12*s,mats.dark,xx,2.7*s,3.58*s);box(g,1.55*s,.15*s,.22*s,mats.wall2,xx,3.36*s,3.58*s)}box(g,10.5*s,.22*s,1.4*s,mats.trunk,0,2.8*s,4.3*s);scene.add(g)}
// island foliage scattered away from the playable center
for(let i=0;i<86;i++){const a=Math.random()*Math.PI*2,r=21+Math.random()*70,x=Math.cos(a)*r,z=Math.sin(a)*r;if(Math.hypot(x-15,z+12)<13||Math.hypot(x+23,z-16)<11)continue;tree(x,z,.65+Math.random()*.55)}
for(const p of [[15,-12,1,0],[24,-14,.78,.7],[-24,16,.9,2.7],[-31,18,.66,2.2],[42,28,.75,1.1]])hut(...p);
for(let i=0;i<38;i++){const a=Math.random()*6.28,r=8+Math.random()*69;rock(Math.cos(a)*r,Math.sin(a)*r,.5+Math.random()*1.1)}
// roads as subtle low-profile strips
const road=new THREE.Mesh(new THREE.PlaneGeometry(9,148),mat(0x9d916d));road.rotation.x=-Math.PI/2;road.position.set(-5,.02,0);road.rotation.z=.12;scene.add(road);
const road2=new THREE.Mesh(new THREE.PlaneGeometry(6,80),mat(0x9d916d));road2.rotation.x=-Math.PI/2;road2.position.set(6,.03,11);road2.rotation.z=1.08;scene.add(road2);

function makeSoldier(isPlayer=false){const g=new THREE.Group();const uniform=isPlayer?mats.player:mats.enemy;const torso=box(g,1.1,1.45,.65,uniform,0,1.75,0);torso.rotation.x=-.04;box(g,.84,.42,.52,mats.pants,0,.86,0);const head=new THREE.Mesh(new THREE.SphereGeometry(.34,10,8),mats.skin);head.position.y=2.78;head.scale.set(.84,1.1,.9);head.castShadow=true;g.add(head);const vest=box(g,1.13,.7,.7,isPlayer?mats.dark:mats.enemy2,0,1.8,-.06);vest.material=vest.material.clone();const legs=[];for(const x of [-.3,.3]){const limb=box(g,.36,.95,.42,mats.pants,x,.45,0);limb.geometry.translate(0,-.45,0);limb.position.y=.9;legs.push(limb)}const arms=[];for(const x of [-.72,.72]){const arm=box(g,.34,1,.36,uniform,x,1.8,-.02);arm.geometry.translate(0,-.42,0);arm.position.y=2;arms.push(arm)}const gun=box(g,.19,.22,1.35,mats.gun,.16,1.86,-.72);box(g,.12,.34,.36,mats.dark,.16,1.6,-.6);const pack=box(g,.68,.85,.35,isPlayer?mats.player:mats.enemy2,0,2.06,.48);pack.material=pack.material.clone();g.userData={legs,arms,gun};g.traverse(o=>{if(o.isMesh){o.castShadow=true;o.receiveShadow=true}});return g}
function makeBar(){const c=document.createElement('canvas');c.width=128;c.height=12;const x=c.getContext('2d');x.fillStyle='#13201d';x.fillRect(0,0,128,12);x.fillStyle='#e87559';x.fillRect(2,2,124,8);const t=new THREE.CanvasTexture(c);const m=new THREE.Sprite(new THREE.SpriteMaterial({map:t,transparent:true,depthTest:false}));m.scale.set(1.4,.13,1);return m}
const player=makeSoldier(true);scene.add(player);player.position.set(0,heightAt(0,0),0);
const bots=[];for(let i=0;i<5;i++){const a=i/5*Math.PI*2+.45,r=34+Math.random()*17,x=Math.cos(a)*r,z=Math.sin(a)*r;const model=makeSoldier(false);model.position.set(x,heightAt(x,z),z);scene.add(model);const bar=makeBar();bar.position.y=3.45;model.add(bar);bots.push({model,bar,hp:100,max:100,alive:true,cooldown:1.5+Math.random()*2,phase:Math.random()*6.28,seed:i})}

