const bots=[];for(let i=0;i<5;i++){const a=i/5*Math.PI*2+.45,r=34+Math.random()*17,x=Math.cos(a)*r,z=Math.sin(a)*r;const model=makeSoldier(false);model.position.set(x,heightAt(x,z),z);scene.add(model);const bar=makeBar();bar.position.y=3.45;model.add(bar);bots.push({model,bar,hp:100,max:100,alive:true,cooldown:1.5+Math.random()*2,phase:Math.random()*6.28,seed:i})}
const state={started:false,over:false,paused:false,hp:100,armor:50,ammo:30,reserve:120,kills:0,medkits:2,grenades:1,elapsed:0,zone:76,zoneStart:85,zoneEnd:25,zoneTime:78,reloading:false,reloadT:0,fireT:0,yaw:0,moveX:0,moveZ:0,sprint:false,aim:false,jumpT:0,velY:0,toastT:0,messageT:0,sound:true};
const keys={};let pointerDown=false,lastPointerX=0,lastPointerY=0,lastShot=0;const raycaster=new THREE.Raycaster();raycaster.far=85;
function setCamera(dt=0){const forward=new THREE.Vector3(Math.sin(state.yaw),0,-Math.cos(state.yaw));const desired=new THREE.Vector3(player.position.x-forward.x*7.3,player.position.y+4.4,player.position.z-forward.z*7.3);camera.position.lerp(desired,Math.min(1,dt*7));const target=new THREE.Vector3(player.position.x+forward.x*2,player.position.y+2.05,player.position.z+forward.z*2);camera.lookAt(target);camera.fov=state.aim?49:62;camera.updateProjectionMatrix()}
function showToast(text,duration=1.5){$('toast').textContent=text;$('toast').style.opacity=1;state.toastT=duration}
function announce(text,duration=2){$('centerMessage').textContent=text;$('centerMessage').style.opacity=1;state.messageT=duration}
let audioCtx=null;function beep(freq=160,duration=.08,type='square',gain=.035){if(!state.sound)return;try{audioCtx ||= new (window.AudioContext||window.webkitAudioContext)();const o=audioCtx.createOscillator(),g=audioCtx.createGain();o.type=type;o.frequency.value=freq;g.gain.setValueAtTime(gain,audioCtx.currentTime);g.gain.exponentialRampToValueAtTime(.001,audioCtx.currentTime+duration);o.connect(g);g.connect(audioCtx.destination);o.start();o.stop(audioCtx.currentTime+duration)}catch{}}
function setHud(){ $('healthNum').textContent=Math.ceil(state.hp);$('healthFill').style.width=Math.max(0,state.hp)+'%';$('armorNum').textContent=Math.ceil(state.armor);$('medCount').textContent=state.medkits;$('magAmmo').textContent=state.ammo;$('reserveAmmo').textContent=state.reserve;$('killCount').textContent=String(state.kills).padStart(2,'0');$('alive').textContent=String(6-state.kills).padStart(2,'0');$('zoneTimer').textContent=state.elapsed<state.zoneTime?fmt(state.zoneTime-state.elapsed):'SHRINKING';}
function fmt(sec){const n=Math.max(0,Math.floor(sec));return `${String(Math.floor(n/60)).padStart(2,'0')}:${String(n%60).padStart(2,'0')}`}
